{"tool": "check_build", "input": {"code": "script({
  title: "Japanese Buddhist Temple (Kondo & Shoro)",
  description: "A sacred Japanese Buddhist temple precinct featuring a double-eaved Kondo (Main Hall) with an open engawa veranda and sanctum with a golden Buddha, a freestanding Shoro (Bell Tower) with bronze bonsho bell, a Chozuya water purification pavilion, Kasuga stone lanterns, and a sculpted Japanese pine.",
  palette: {
    stone: { mix: ["light bluish grey", "dark bluish grey"] },
    timber: "reddish brown",
    dark_timber: "dark brown",
    wall: "white",
    roof: "dark bluish grey",
    gold: "pearl gold",
    water: "trans light blue",
    foliage: "dark green"
  }
});

// --- Precinct Base & Courtyard Paths ---
section("Courtyard", [
  // Stone terrace ground footing
  floor({ at: [-26, 0, -18], size: [52, 40], colour: "dark bluish grey", layers: 1 }),
  // Central stone sandō path
  floor({ at: [-4, 1, -18], size: [8, 18], colour: "stone", layers: 1, top: "tile" }),
  // Stepping stones to bell tower
  floor({ at: [-18, 1, -8], size: [14, 4], colour: "stone", layers: 1, top: "tile" }),
  // Stepping stones to water pavilion
  floor({ at: [4, 1, -8], size: [14, 4], colour: "stone", layers: 1, top: "tile" })
]);

// --- Main Hall (Kondo / Hondo) Foundation & Veranda ---
section("Kondo_Platform", [
  // Raised podium (Dan)
  box({ at: [-14, 1, 0], size: [28, 3, 20], colour: "stone", interior: "solid" }),
  // Front access stone steps
  stairs({ at: [-3, 1, -3], width: 6, steps: 3, dir: "+z", rise: 1, run: 1, colour: "light bluish grey" }),
  // Engawa wooden veranda deck
  floor({ at: [-14, 4, 0], size: [28, 20], colour: "timber", layers: 1, top: "tile" })
]);

// --- Main Hall Structure & Sanctum ---
section("Kondo_Hall", [
  // Sanctum chamber walls
  room({
    at: [-10, 5, 4],
    size: [20, "5b", 14],
    colour: "wall",
    openings: [
      // Main front entrance into the sanctum
      { side: "front", at: 7, width: 6, height: 15, fill: "none" },
      // Flanking window openings
      { side: "front", at: 2, width: 3, y: 3, height: 9, fill: "none" },
      { side: "front", at: 15, width: 3, y: 3, height: 9, fill: "none" }
    ]
  }),
  // Front sliding shoji lattices
  place({ part: "3185", at: [-8, 8, 4], colour: "reddish brown", turn: 0 }),
  place({ part: "3185", at: [5, 8, 4], colour: "reddish brown", turn: 0 }),
  // Perimeter veranda timber columns (10 columns around the engawa)
  ...[-12, -7, -2, 3, 8, 12].map(x => column({ at: [x, 5, 1], height: 15, diameter: 1, colour: "dark_timber" })),
  ...[-12, 12].flatMap(x => [6, 11, 16, 18].map(z => column({ at: [x, 5, z], height: 15, diameter: 1, colour: "dark_timber" }))),
  // Veranda balustrade railing
  fence({ path: [[-13, 1], [-13, 19], [13, 19], [13, 1]], y: 5, colour: "timber", style: "spindle" }),
  fence({ path: [[-13, 1], [-4, 1]], y: 5, colour: "timber", style: "spindle" }),
  fence({ path: [[4, 1], [13, 1]], y: 5, colour: "timber", style: "spindle" }),

  // --- Sanctum Interior: Golden Buddha & Altar ---
  // Lotus pedestal
  place({ part: "4032b", at: [-1, 5, 12], colour: "gold" }),
  place({ part: "4740", at: [-1, 6, 12], colour: "gold" }),
  // Seated Buddha
  place({ part: "3003", at: [-1, 7, 12], colour: "gold" }),
  place({ part: "3024", at: [-1, 10, 12], colour: "gold" }),
  place({ part: "3005", at: [0, 10, 12], colour: "gold" }),
  place({ part: "3022", at: [-1, 11, 12], colour: "gold" }),
  // Mandorla (Golden halo)
  place({ part: "3960", at: [-2, 8, 14], colour: "gold", turn: 0 }),
  // Altar table
  box({ at: [-2, 5, 8], size: [4, 3, 2], colour: "dark_timber", interior: "solid" }),
  place({ part: "6141", at: [-1, 8, 8], colour: "gold" }),
  place({ part: "6141", at: [1, 8, 8], colour: "gold" }),
  place({ part: "4589", at: [0, 8, 8], colour: "pearl gold" })
]);

// --- Kondo Double-Eaved Roofs ---
section("Kondo_Roof", [
  // Dougong bracket clusters along eaves
  ...[-12, -7, -2, 3, 8, 12].map(x => place({ part: "3665a", at: [x, 20, 0], colour: "dark_timber", turn: 0 })),
  // Lower Mokoshi Eave Hip Roof with central opening
  roof({
    style: "hip",
    at: [-14, 20, -1],
    size: [28, 22],
    colour: "roof",
    overhang: 1,
    holes: [{ at: [-8, 5], size: [16, 10] }]
  }),
  // Upper Clerestory Core
  box({ at: [-8, 20, 5], size: [16, 9, 10], colour: "wall", interior: "empty" }),
  // Upper timber framing pilasters
  ...[-8, -4, 0, 4, 7].map(x => column({ at: [x, 20, 4], height: 9, diameter: 1, colour: "dark_timber" })),
  ...[-8, -4, 0, 4, 7].map(x => column({ at: [x, 20, 15], height: 9, diameter: 1, colour: "dark_timber" })),
  // Upper Dougong bracket clusters
  ...[-8, -3, 2, 7].map(x => place({ part: "3665a", at: [x, 29, 3], colour: "dark_timber", turn: 0 })),
  // Upper Grand Hip-and-Gable Roof
  roof({
    style: "hip",
    at: [-10, 29, 3],
    size: [20, 14],
    colour: "roof",
    overhang: 1
  })
]);

// --- Bell Tower (Shorō) ---
section("Bell_Tower", [
  // Stone foundation
  box({ at: [-22, 1, -14], size: [8, 3, 8], colour: "stone", interior: "solid" }),
  // 4 corner timber pillars
  column({ at: [-21, 4, -13], height: 18, diameter: 1, colour: "dark_timber" }),
  column({ at: [-16, 4, -13], height: 18, diameter: 1, colour: "dark_timber" }),
  column({ at: [-21, 4, -8], height: 18, diameter: 1, colour: "dark_timber" }),
  column({ at: [-16, 4, -8], height: 18, diameter: 1, colour: "dark_timber" }),
  // Crossbeams
  box({ at: [-22, 21, -14], size: [8, 1, 8], colour: "dark_timber", open: ["top"] }),
  // Bronze Buddhist Bell (Bonshō)
  place({ part: "4740", at: [-19, 16, -11], colour: "dark bluish grey", turn: 0 }),
  place({ part: "3941", at: [-19, 13, -11], colour: "dark bluish grey" }),
  place({ part: "3062b", at: [-19, 10, -11], colour: "dark bluish grey" }),
  // Striking wooden beam (Shumoku)
  place({ part: "2431", at: [-16, 12, -10], colour: "timber", turn: 90 }),
  // Bell tower flared roof
  roof({
    style: "hip",
    at: [-23, 22, -15],
    size: [10, 10],
    colour: "roof",
    overhang: 1
  })
]);

// --- Water Purification Pavilion (Chōzuya) ---
section("Chozuya", [
  // Stone floor pad
  floor({ at: [14, 1, -14], size: [8, 8], colour: "stone", layers: 1, top: "tile" }),
  // 4 wooden posts
  column({ at: [15, 2, -13], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [20, 2, -13], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [15, 2, -8], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [20, 2, -8], height: 12, diameter: 1, colour: "dark_timber" }),
  // Stone water basin (Tsukubai)
  box({ at: [17, 2, -11], size: [3, 4, 3], colour: "dark bluish grey", interior: "empty" }),
  floor({ at: [17, 4, -11], size: [3, 3], colour: "water", layers: 1, top: "tile" }),
  // Bamboo water spout
  place({ part: "4599b", at: [16, 5, -10], colour: "dark green", turn: 270 }),
  // Gable roof
  roof({
    style: "gable",
    at: [14, 14, -14],
    size: [8, 8],
    colour: "roof",
    gable: "dark_timber",
    overhang: 1
  })
]);

// --- Kasuga Stone Lanterns (Tōrō) ---
const stoneLantern = (at) => [
  place({ part: "3022", at: [at[0], at[1], at[2]], colour: "dark bluish grey" }),
  place({ part: "3062b", at: [at[0], at[1] + 1, at[2]], colour: "light bluish grey" }),
  place({ part: "3660b", at: [at[0], at[1] + 4, at[2]], colour: "dark bluish grey" }),
  place({ part: "4070", at: [at[0], at[1] + 7, at[2]], colour: "light bluish grey" }),
  place({ part: "6141", at: [at[0], at[1] + 7, at[2] - 1], colour: "trans yellow" }),
  place({ part: "3039", at: [at[0], at[1] + 10, at[2]], colour: "dark bluish grey" }),
  place({ part: "4589", at: [at[0], at[1] + 13, at[2]], colour: "light bluish grey" })
];

section("Lanterns", [
  ...stoneLantern([-6, 1, -12]),
  ...stoneLantern([5, 1, -12])
]);

// --- Sculpted Japanese Black Pine (Matsu) ---
section("Pine_Tree", [
  // Gnarled trunk stepping up and leaning
  column({ at: [21, 1, 6], height: 9, diameter: 2, colour: "dark_timber" }),
  column({ at: [20, 10, 6], height: 6, diameter: 2, colour: "dark_timber" }),
  column({ at: [18, 16, 7], height: 6, diameter: 1, colour: "dark_timber" }),
  // Tiered cloud foliage pads
  place({ part: "2417", at: [18, 12, 3], colour: "foliage", turn: 0 }),
  place({ part: "2423", at: [19, 13, 4], colour: "dark green", turn: 90 }),
  place({ part: "2417", at: [16, 18, 5], colour: "foliage", turn: 180 }),
  place({ part: "2423", at: [17, 19, 6], colour: "dark green", turn: 270 }),
  place({ part: "2417", at: [15, 22, 6], colour: "foliage", turn: 0 })
]);
", "seed": 1}}

