  // Stepping stones to bell tower
  floor({ at: [-18, 1, -8], size: [14, 4], colour: "stone", layers: 1, top: "tile" }),
  // Stepping stones to water pavilion
  floor({ at: [4, 1, -8], size: [14, 4], colour: "stone", layers: 1, top: "tile" })
]);

// --- Main Hall (Kondo / Hondo) Foundation & Veranda ---
section("Kondo_Platform", [
  // Raised podium (Dan)
  box({ at: [-14, 1, 0], size: [28, 3, 20], colour: "stone", interior: "solid" }),
  // Front access stone steps
  stairs({ at: [-3, 1, -3], width: 6, steps: 3, dir: "+z", rise: 1, run: 1, colour: "light bluish grey" }),
  // Engawa wooden veranda deck
  floor({ at: [-14, 4, 0], size: [28, 20], colour: "timber", layers: 1, top: "tile" })
