// --- Main Hall Structure & Sanctum ---
section("Kondo_Hall", [
  // Sanctum chamber walls
  room({
    at: [-10, 5, 4],
    size: [20, "5b", 14],
    colour: "wall",
    openings: [
      // Main front entrance into the sanctum
      { side: "front", at: 7, width: 6, height: 15, fill: "none" },
      // Flanking window openings
      { side: "front", at: 2, width: 3, y: 3, height: 9, fill: "none" },
      { side: "front", at: 15, width: 3, y: 3, height: 9, fill: "none" }
