  fence({ path: [[-13, 1], [-4, 1]], y: 5, colour: "timber", style: "spindle" }),
  fence({ path: [[4, 1], [13, 1]], y: 5, colour: "timber", style: "spindle" }),

  // --- Sanctum Interior: Golden Buddha & Altar ---
  // Lotus pedestal
  place({ part: "4032b", at: [-1, 5, 12], colour: "gold" }),
