  place({ part: "3022", at: [-1, 11, 12], colour: "gold" }),
  // Mandorla (Golden halo)
  place({ part: "3960", at: [-2, 8, 14], colour: "gold", turn: 0 }),
  // Altar table
  box({ at: [-2, 5, 8], size: [4, 3, 2], colour: "dark_timber", interior: "solid" }),
  place({ part: "6141", at: [-1, 8, 8], colour: "gold" }),
  place({ part: "6141", at: [1, 8, 8], colour: "gold" }),
  place({ part: "4589", at: [0, 8, 8], colour: "pearl gold" })
