// --- Kondo Double-Eaved Roofs ---
section("Kondo_Roof", [
  // Dougong bracket clusters along eaves
  ...[-12, -7, -2, 3, 8, 12].map(x => place({ part: "3665a", at: [x, 20, 0], colour: "dark_timber", turn: 0 })),
