  box({ at: [-22, 21, -14], size: [8, 1, 8], colour: "dark_timber", open: ["top"] }),
  // Bronze Buddhist Bell (Bonshō)
  place({ part: "4740", at: [-19, 16, -11], colour: "dark bluish grey", turn: 0 }),
  place({ part: "3941", at: [-19, 13, -11], colour: "dark bluish grey" }),
  place({ part: "3062b", at: [-19, 10, -11], colour: "dark bluish grey" }),
  // Striking wooden beam (Shumoku)
  place({ part: "2431", at: [-16, 12, -10], colour: "timber", turn: 90 }),
  // Bell tower flared roof
  roof({
    style: "hip",
    at: [-23, 22, -15],
    size: [10, 10],
    colour: "roof",
    overhang: 1
  })
]);

// --- Water Purification Pavilion (Chōzuya) ---
section("Chozuya", [
  // Stone floor pad
  floor({ at: [14, 1, -14], size: [8, 8], colour: "stone", layers: 1, top: "tile" }),
  // 4 wooden posts
  column({ at: [15, 2, -13], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [20, 2, -13], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [15, 2, -8], height: 12, diameter: 1, colour: "dark_timber" }),
  column({ at: [20, 2, -8], height: 12, diameter: 1, colour: "dark_timber" }),
  // Stone water basin (Tsukubai)
  box({ at: [17, 2, -11], size: [3, 4, 3], colour: "dark bluish grey", interior: "empty" }),
  floor({ at: [17, 4, -11], size: [3, 3], colour: "water", layers: 1, top: "tile" }),
  // Bamboo water spout
  place({ part: "4599b", at: [16, 5, -10], colour: "dark green", turn: 270 }),
  // Gable roof
  roof({
    style: "gable",
    at: [14, 14, -14],
    size: [8, 8],
    colour: "roof",
    gable: "dark_timber",
    overhang: 1
  })
]);

// --- Kasuga Stone Lanterns (Tōrō) ---
const stoneLantern = (at) => [
  place({ part: "3022", at: [at[0], at[1], at[2]], colour: "dark bluish grey" }),
  place({ part: "3062b", at: [at[0], at[1] + 1, at[2]], colour: "light bluish grey" }),
  place({ part: "3660b", at: [at[0], at[1] + 4, at[2]], colour: "dark bluish grey" }),
  place({ part: "4070", at: [at[0], at[1] + 7, at[2]], colour: "light bluish grey" }),
  place({ part: "6141", at: [at[0], at[1] + 7, at[2] - 1], colour: "trans yellow" }),
  place({ part: "3039", at: [at[0], at[1] + 10, at[2]], colour: "dark bluish grey" }),
  place({ part: "4589", at: [at[0], at[1] + 13, at[2]], colour: "light bluish grey" })
