// --- Sculpted Japanese Black Pine (Matsu) ---
section("Pine_Tree", [
  // Gnarled trunk stepping up and leaning
  column({ at: [21, 1, 6], height: 9, diameter: 2, colour: "dark_timber" }),
  column({ at: [20, 10, 6], height: 6, diameter: 2, colour: "dark_timber" }),
  column({ at: [18, 16, 7], height: 6, diameter: 1, colour: "dark_timber" }),
