  place({ part: "2417", at: [18, 12, 3], colour: "foliage", turn: 0 }),
  place({ part: "2423", at: [19, 13, 4], colour: "dark green", turn: 90 }),
  place({ part: "2417", at: [16, 18, 5], colour: "foliage", turn: 180 }),
  place({ part: "2423", at: [17, 19, 6], colour: "dark green", turn: 270 }),
  place({ part: "2417", at: [15, 22, 6], colour: "foliage", turn: 0 })
]);

